<?php

namespace Ediligence\EdiligenceBundle\Repository;

Use Doctrine\ORM\Query\Expr\Join;

/**
 * TreceptionRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class Tmp_traitementRepository extends \Doctrine\ORM\EntityRepository {

    public function max_traitements($courrier, $imput, $imputdir) {
        $qb = $this->createQueryBuilder('t')
                ->select('count(t.id) AS max_enreg')
                ->where('t.codecourrier=:courrier and t.idImput=:imput and t.imputdir=:imputdir and t.etattraitement=:etattraitement')
                ->setParameter("courrier", $courrier)
                ->setParameter("imput", $imput)
                ->setParameter("imputdir", $imputdir)
                ->setParameter("etattraitement", 1)
                ->setMaxResults(1);
        return $qb->getQuery()->getOneOrNullResult();
    }

    public function trt_list($matricule) {
        $qb = $this->createQueryBuilder('t')
                ->Distinct()
                ->addSelect('i.dateImput, c.objet, p.lib as sourceCour')
                ->innerJoin('EdiligenceBundle:Timputations', 'i', Join::WITH, 't.idImput = i.id')
                ->innerJoin('EdiligenceBundle:Tcourrier', 'c', Join::WITH, 'i.courrier = c.id')
                ->innerJoin('c.sourceCour', 'p')
                ->where('t.matriculeimpute =:matriculeimpute')
                ->setParameter('matriculeimpute', $matricule);

        return $qb->getQuery()->getResult();
    }

    public function diligence_traite($mat, $service, $role) {
        //recuperer le max
        if ($role == 'ROLE_DGE') {
            $qb1 = $this->createQueryBuilder('t')
                    ->distinct()
                    ->select('t.id as q')
                    ->where('t.etattraitement =:etattraitement')
                    ->andWhere("t.matriculeimputeur='" . $mat . "' ")
                    //->groupBy('t.codecourrier')
                    ->orderBy('t.id', 'DESC')
                    ->setParameter('etattraitement', 0)
                    ->setMaxResults(1);
            $qb1 = $qb1->getQuery()->getResult();

            if ($qb1) {
                $rec = $qb1[0]['q'];
            } else {
                $rec = null;
            }

            //dump(123);dump($qb1);dump($qb1[0]['q']);die;
        } else {
            $rec = null;
        }

        // dump($rec);die;
        $qb = $this->createQueryBuilder('t')
                ->distinct()
                ->select('t.id,t.matriculeimpute,a.nom, a.prenoms, a.nomJeuneFille, c.objet, t.datetraitement'
                        . ',b.nom as nom_dest, b.prenoms as pren_dest, b.nomJeuneFille as jfil_dest, p as pj')
                ->innerJoin('AgentBundle:Agent', 'a', Join::WITH, 't.matriculeimpute = a.matricule')
                ->innerJoin('EdiligenceBundle:Tcourrier', 'c', Join::WITH, 't.codecourrier = c.id')
                ->leftJoin('EdiligenceBundle:Ttraitement', 'y', Join::WITH, 't.codecourrier = y.codecourrier And y.etattraitement = 0 ')
                ->innerJoin('AgentBundle:Agent', 'b', Join::WITH, 't.matriculeimputeur = b.matricule')
                ->innerJoin('AgentBundle:Pj', 'p', Join::WITH, 't.pjtraitement = p.id')
                ->where('t.etattraitement =:etattraitement ')
                ->andWhere("t.matriculeimputeur='" . $mat . "' "); //t.matriculeimpute ='".$mat."' Or And y.codecourrier Is null
        if ($rec != null) {
            $qb->andWhere("t.id=$rec")
                    ->andWhere("y.etattraitement = 0");
        }
        $qb->setParameter('etattraitement', 0);
        //->setParameter('desactive', 0)
//dump($qb->getQuery()->getResult());die;
        return $qb->getQuery()->getResult();
    }

    public function findtrt($traitement) {
        $qb = $this->createQueryBuilder('t')
                ->select('t.id, c.objet, t.datetraitement, t.numtraitement,tc.id as typecourrier,tc.libcourrier as lib, t.libtraitement, t.matriculeimpute, t.codecourrier, t.idImput, i.dateImput, i.etatImput, a.nom, a.prenoms, a.nomJeuneFille, b.nom as nom_dest, b.prenoms as pren_dest, b.nomJeuneFille as jfil_dest,p as pj, a.matricule as mat_emetteur, b.matricule as mat_destinataire')
                ->innerJoin('EdiligenceBundle:Tcourrier', 'c', Join::WITH, 't.codecourrier = c.id')
                ->innerJoin('EdiligenceBundle:Timputations', 'i', Join::WITH, 't.idImput = i.id')
                ->innerJoin('AgentBundle:Pj', 'p', Join::WITH, 't.pjtraitement = p.id')
                ->innerJoin('AgentBundle:Agent', 'a', Join::WITH, 't.matriculeimpute = a.matricule')
                ->innerJoin('AgentBundle:Agent', 'b', Join::WITH, 't.matriculeimputeur = b.matricule')
                ->innerJoin('c.typecourrier', 'tc')
                ->where('t.id=:id')
                ->setParameter('id', $traitement);
        return $qb->getQuery()->getResult();
    }

    public function recap_trait($matricule, $imputation) {
        $qb1 = $this->createQueryBuilder('t')
                ->select('t, M.nom, M.prenoms, M.nomJeuneFille')
                ->innerJoin('EdiligenceBundle:Tcourrier', 'c', Join::WITH, 't.codecourrier = c.id')
                ->LeftJoin('EdiligenceBundle:Tarchive', 'a', Join::WITH, 't.codecourrier = a.codecourrier') 
                ->innerJoin('EdiligenceBundle:Timputations', 'i', Join::WITH, 't.idImput = i.id')
                ->innerJoin('EdiligenceBundle:Ttypecourrier', 'typ', Join::WITH, 'c.typecourrier = typ.id')
                ->InnerJoin('AgentBundle:Pj', 'j', Join::WITH, 'c.piecejointe = j.id')
                
                ->LeftJoin('AgentBundle:Pj', 'p', Join::WITH, 't.pjtraitement = p.id')
                ->InnerJoin('AgentBundle:Agent', 'M', Join::WITH, 't.matriculeimpute = M.matricule')
                ->where("t.idImput = :idImput And a.id Is Null ")
                ->andWhere("t.matriculeimpute = :matriculeimpute Or t.matriculeimputeur = :matriculeimpute ")

                ->setParameter("matriculeimpute", $matricule)
                ->setParameter("idImput", $imputation);
//dump($imputation);dump($qb1->getQuery()->getResult());die;
        $qb2 = $this->getEntityManager()->createQueryBuilder()
                ->select('i')
                ->from('EdiligenceBundle:Timputations', 'i')
                ->innerJoin('i.courrier', 'c')
                ->where("i.id = :idImput")
                ->setParameter("idImput", $imputation);

        /*
        $qb2 = $this->createQueryBuilder('t')
                ->select('c')
                ->innerJoin('EdiligenceBundle:Tcourrier', 'c', Join::WITH, 't.codecourrier = c.id')
                ->innerJoin('EdiligenceBundle:Ttypecourrier', 'typ', Join::WITH, 'c.typecourrier = typ.id')
