                ->LeftJoin('EdiligenceBundle:Tarchive', 'a', Join::WITH, 't.codecourrier = a.id')
                ->LeftJoin('AgentBundle:Pj', 'p', Join::WITH, 't.pjtraitement = p.id')
                ->where("t.idImput = :idImput And a.id Is Null")
                ->orWhere("t.matriculeimpute = :matriculeimpute ")
                ->orWhere("t.matriculeimputeur = :matriculeimpute")
                ->setParameter("matriculeimpute", $matricule)
                ->setParameter("idImput", $imputation);*/

        return ['trait' => $qb1->getQuery()->getResult(), 'courrier' => $qb2->getQuery()->getOneOrNullResult()];
